    setupEventListeners() {
        // Real-time validation on blur and input
        const inputs = this.form.querySelectorAll('input[type="text"], input[type="email"], input[type="tel"]');
        inputs.forEach(input => {
            input.addEventListener('blur', () => this.validateField(input));
            input.addEventListener('input', () => {
                if (input.classList.contains('touched')) {
                    this.validateField(input);
                }
            });
        });

        // Form submission
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
    }

    validateField(input) {
        const fieldName = input.name;
        const value = input.value.trim();
        const errorElement = document.getElementById(`${input.id}-error`);

        input.classList.add('touched');
        let errorMessage = '';

        // Full Name validation
        if (fieldName === 'fullName') {
            if (!value) {
                errorMessage = 'Full name is required';
            } else if (value.length < 2) {
                errorMessage = 'Full name must be at least 2 characters';
            }
        }

        // Email validation
        if (fieldName === 'email') {
            if (!value) {
                errorMessage = 'Email address is required';
            } else if (!this.isValidEmail(value)) {
                errorMessage = 'Please enter a valid email address';
            }
        }

        // Phone validation (optional, but validate format if provided)
        if (fieldName === 'phone') {
            if (value && !this.isValidPhone(value)) {
                errorMessage = 'Please enter a valid phone number';
            }
        }

        // Update error message and validation state
        errorElement.textContent = errorMessage;

        if (errorMessage) {
            input.setAttribute('aria-invalid', 'true');
        } else {
            input.setAttribute('aria-invalid', 'false');
        }

        return !errorMessage;
    }

    isValidEmail(email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }

    isValidPhone(phone) {
        // Accepts formats like: (123) 456-7890, 123-456-7890, 123.456.7890, 1234567890
        const phoneRegex = /^(\+?1[-.\s]?)?\(?([0-9]{3})\)?[-.\s]?([0-9]{3})[-.\s]?([0-9]{4})$/;
        return phoneRegex.test(phone.replace(/\s/g, ''));
    }

    validateForm() {
        const inputs = this.form.querySelectorAll('input[type="text"], input[type="email"], input[type="tel"]');
        let isValid = true;

        inputs.forEach(input => {
            input.classList.add('touched');
            if (!this.validateField(input)) {
                isValid = false;
            }
        });

        return isValid;
    }

    handleSubmit(e) {
        e.preventDefault();

        // Validate all fields
        if (!this.validateForm()) {
            // Focus on first invalid field
            const firstInvalid = this.form.querySelector('[aria-invalid="true"]');
            if (firstInvalid) {
                firstInvalid.focus();
            }
            return;
        }

        // Simulate form submission
        this.submitForm();
    }

    submitForm() {
        const fullName = document.getElementById('fullName').value.trim();
        const email = document.getElementById('email').value.trim();
        const phone = document.getElementById('phone').value.trim();

        const submitButton = this.form.querySelector('button[type="submit"]');
        const successElement = document.getElementById('submitSuccess');

        // Disable button during submission
        submitButton.disabled = true;
        submitButton.textContent = 'Sending...';

        // Simulate API call
        setTimeout(() => {
            // Reset button state
            submitButton.disabled = false;
            submitButton.textContent = 'Send Message';

            // Show success message
            successElement.textContent = `Thank you, ${fullName}! We've received your message and will get back to you at ${email} soon.`;

            // Reset form
            this.form.reset();

